package com.teeniv.whatsapp;
import android.net.Uri;import android.os.Bundle;import android.widget.*;import androidx.activity.result.ActivityResultLauncher;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import com.bumptech.glide.Glide;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.database.*;import com.google.firebase.storage.FirebaseStorage;
public class ProfileActivity extends AppCompatActivity {
 String uid;Uri selected;ImageView photo;EditText name;ActivityResultLauncher<String> picker;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_profile);uid=FirebaseAuth.getInstance().getUid();photo=findViewById(R.id.profilePhoto);name=findViewById(R.id.profileName);((TextView)findViewById(R.id.profileEmail)).setText(FirebaseAuth.getInstance().getCurrentUser().getEmail());FirebaseDatabase.getInstance().getReference("users").child(uid).get().addOnSuccessListener(s->{User u=s.getValue(User.class);if(u!=null){name.setText(u.name);if(u.photoUrl!=null&&!u.photoUrl.isEmpty())Glide.with(this).load(u.photoUrl).circleCrop().into(photo);}});picker=registerForActivityResult(new ActivityResultContracts.GetContent(),uri->{if(uri!=null){selected=uri;photo.setImageURI(uri);}});findViewById(R.id.changePhoto).setOnClickListener(v->picker.launch("image/*"));findViewById(R.id.saveProfile).setOnClickListener(v->save());}
 void save(){String n=name.getText().toString().trim();if(n.isEmpty()){Toast.makeText(this,"Enter a display name",Toast.LENGTH_SHORT).show();return;}if(selected!=null){FirebaseStorage.getInstance().getReference("profilePhotos/"+uid+".jpg").putFile(selected).addOnSuccessListener(t->t.getStorage().getDownloadUrl().addOnSuccessListener(u->saveUser(n,u.toString()))).addOnFailureListener(e->toast(e.getLocalizedMessage()));}else saveUser(n,null);}
 void saveUser(String n,String url){DatabaseReference ref=FirebaseDatabase.getInstance().getReference("users").child(uid);ref.child("name").setValue(n);if(url!=null)ref.child("photoUrl").setValue(url);Toast.makeText(this,"Profile saved",Toast.LENGTH_SHORT).show();finish();}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
}
